1	import Domain
2	import DuckDB
3	import Foundation
4	import Logging
5	
6	// MARK: - Database path registry
7	
8	/// Thread-safe global registry mapping `Database` identity → file URL.
9	/// Populated by `DuckDBReaderActor.init(databasePath:)` so that
10	/// `DuckDBWriterActor.backupDatabase(to:)` can resolve the source path
11	/// even when the writer was constructed with only a `Database` reference.
12	enum DatabasePathRegistry {
13	    private static let lock = NSLock()
14	    // nonisolated(unsafe): access is fully serialized by `lock` above.
15	    private nonisolated(unsafe) static var store: [ObjectIdentifier: URL] = [:]
16	
17	    static func register(database: Database, path: URL) {
18	        lock.withLock { store[ObjectIdentifier(database)] = path }
19	    }
20	
21	    static func path(for database: Database) -> URL? {
22	        lock.withLock { store[ObjectIdentifier(database)] }
23	    }
24	}
25	
26	// MARK: - DuckDBWriterActor
27	
28	public actor DuckDBWriterActor: RecordingWriteRepository, DiarizationWriteRepository, NotesWriteRepository, SummaryWriteRepository, TranscriptWriteRepository, WordTimingsWriteRepository {
29	    private let writeQueue = DispatchSerialQueue(label: "app.the-record.duckdb.writer", qos: .userInitiated)
30	    public nonisolated var unownedExecutor: UnownedSerialExecutor {
31	        writeQueue.asUnownedSerialExecutor()
32	    }
33	
34	    let database: Database
35	    let connection: Connection
36	    let logger = AppLogger.for(category: "DuckDBWriter")
37	
38	    /// The file URL of the database backing store, or `nil` for in-memory databases.
39	    /// Used by `backupDatabase(to:)` to locate the source file.
40	    let databasePath: URL?
41	
42	    public init(database: Database, databasePath: URL? = nil) throws {
43	        self.database = database
44	        self.databasePath = databasePath
45	        do {
46	            self.connection = try database.connect()
47	        } catch {
48	            throw StorageError.writeFailed(underlying: error)
49	        }
50	    }
51	
52	    func prepared(_ sql: String) throws -> PreparedStatement {
53	        try PreparedStatement(connection: connection, query: sql)
54	    }
55	
56	    // MARK: - Backup
57	
58	    /// Copies the primary database file to `destination`. Overwrites any existing backup.
59	    /// - Parameter destination: The URL to write the backup file to (e.g. `therecord.duckdb.bak`).
60	    /// - Throws: `StorageError.writeFailed` if no database path is available or the copy fails.
61	    public func backupDatabase(to destination: URL) async throws {
62	        // Prefer explicit databasePath; fall back to global registry; finally query PRAGMA database_list.
63	        let source = databasePath ?? DatabasePathRegistry.path(for: database) ?? resolvedDatabasePath()
64	        guard let source else {
65	            throw StorageError.writeFailed(underlying: nil)
66	        }
67	        try await backupDatabase(source: source, to: destination)
68	    }
69	
70	    /// Queries `PRAGMA database_list` on the current connection to determine the backing file.
71	    /// Returns nil for in-memory databases (file column is empty string).
72	    private func resolvedDatabasePath() -> URL? {
73	        guard let result = try? connection.query("PRAGMA database_list"),
74	              result.rowCount > 0 else { return nil }
75	        // PRAGMA database_list columns: seq (INT32), name (VARCHAR), file (VARCHAR)
76	        let fileCol = result[2].cast(to: String.self)
77	        for i in 0 ..< result.rowCount {
78	            if let path = fileCol[i], !path.isEmpty {
79	                return URL(fileURLWithPath: path)
80	            }
81	        }
82	        return nil
83	    }
84	
85	    /// Copies `source` database file to `destination`. Overwrites any existing backup.
86	    public func backupDatabase(source: URL, to destination: URL) async throws {
87	        do {
88	            if FileManager.default.fileExists(atPath: destination.path) {
89	                try FileManager.default.removeItem(at: destination)
90	            }
91	            try FileManager.default.copyItem(at: source, to: destination)
92	        } catch {
93	            throw StorageError.writeFailed(underlying: error)
94	        }
95	    }
96	}
97	
98	// MARK: - Backup
99	
100	public extension DuckDBWriterActor {
101	
102	    /// Backs up the writer's own database file to `destination`.
103	    ///
104	    /// Issues CHECKPOINT to flush the WAL before copying so the on-disk file
105	    /// is consistent. Overwrites any existing file at `destination` (single-generation).
106	    ///
107	    /// - Throws: `StorageError.writeFailed` when the database is in-memory (no
108	    ///   file path) or when the file copy fails. Errors are catchable — callers
109	    ///   should log and continue rather than crashing (best-effort backup).
110	    func backupDatabase(to destination: URL) async throws {
111	        try connection.execute("CHECKPOINT")
112	
113	        // duckdb_databases() introspection: returns (database_name, path, comment, tags, readonly).
114	        // Filter out in-memory rows whose path is the empty string.
115	        let result = try connection.query(
116	            "SELECT path FROM duckdb_databases() WHERE path != '' LIMIT 1"
117	        )
118	        let filePaths = result[0].cast(to: String.self)
119	        guard let rawPath = filePaths[0], !rawPath.isEmpty else {
120	            throw StorageError.writeFailed(underlying: nil)
121	        }
122	        try Self.copyFile(from: URL(fileURLWithPath: rawPath), to: destination)
123	    }
124	
125	    /// Backs up an arbitrary `source` database file to `destination`.
126	    ///
127	    /// The writer actor holds the exclusive write lock during the copy.
128	    /// CHECKPOINT is attempted as a best-effort WAL flush — failure is logged
129	    /// internally and does not abort the backup (the caller's source file may
130	    /// belong to a different database instance).
131	    /// Overwrites any existing file at `destination` (single-generation).
132	    func backupDatabase(source: URL, to destination: URL) async throws {
133	        // Best-effort WAL flush; ignore failure — source may not be our database.
134	        try? connection.execute("CHECKPOINT")
135	        try Self.copyFile(from: source, to: destination)
136	    }
137	
138	    // MARK: - Private helpers
139	
140	    private static func copyFile(from source: URL, to destination: URL) throws {
141	        let fm = FileManager.default
142	        // Remove any existing backup before copying (single-generation — no rotation).
143	        if fm.fileExists(atPath: destination.path) {
144	            do {
145	                try fm.removeItem(at: destination)
146	            } catch {
147	                throw StorageError.writeFailed(underlying: error)
148	            }
149	        }
150	        do {
151	            try fm.copyItem(at: source, to: destination)
152	        } catch {
153	            throw StorageError.writeFailed(underlying: error)
154	        }
155	    }
