7	public actor DuckDBReaderActor: DiarizationReadRepository, NotesReadRepository, RecordingReadRepository, SummaryReadRepository, TranscriptReadRepository {
8	    private let storageQueue = DispatchSerialQueue(label: "app.the-record.duckdb", qos: .utility)
9	    public nonisolated var unownedExecutor: UnownedSerialExecutor {
10	        storageQueue.asUnownedSerialExecutor()
11	    }
12	
13	    public let database: Database
14	    // internal (not private): DuckDBReaderActorAdmin.swift accesses these via a cross-file
15	    // extension in the same module. Swift private is file-scoped; actor isolation is the
16	    // actual safety boundary here.
17	    let connection: Connection
18	    let logger = AppLogger.for(category: "DuckDBStorage")
19	
20	    public init(databasePath: URL?) throws {
21	        do {
22	            let store: Database.Store = if let path = databasePath {
23	                .file(at: path)
24	            } else {
25	                .inMemory
