import Domain
import DuckDB
import Foundation
import Logging

// MARK: - Database path registry

/// Thread-safe global registry mapping `Database` identity → file URL.
/// Populated by `DuckDBReaderActor.init(databasePath:)` so that
/// `DuckDBWriterActor.backupDatabase(to:)` can resolve the source path
/// even when the writer was constructed with only a `Database` reference.
enum DatabasePathRegistry {
    private static let lock = NSLock()
    // nonisolated(unsafe): access is fully serialized by `lock` above.
    private nonisolated(unsafe) static var store: [ObjectIdentifier: URL] = [:]

    static func register(database: Database, path: URL) {
        lock.withLock { store[ObjectIdentifier(database)] = path }
    }

    static func path(for database: Database) -> URL? {
        lock.withLock { store[ObjectIdentifier(database)] }
    }
}

// MARK: - DuckDBWriterActor

public actor DuckDBWriterActor: RecordingWriteRepository, DiarizationWriteRepository, NotesWriteRepository, SummaryWriteRepository, TranscriptWriteRepository, WordTimingsWriteRepository {
    private let writeQueue = DispatchSerialQueue(label: "app.the-record.duckdb.writer", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        writeQueue.asUnownedSerialExecutor()
    }

    let database: Database
    let connection: Connection
    let logger = AppLogger.for(category: "DuckDBWriter")

    /// The file URL of the database backing store, or `nil` for in-memory databases.
    /// Used by `backupDatabase(to:)` to locate the source file.
    let databasePath: URL?

    public init(database: Database, databasePath: URL? = nil) throws {
        self.database = database
        self.databasePath = databasePath
        do {
            self.connection = try database.connect()
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }

    func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)
    }

    // MARK: - Backup

    /// Copies the primary database file to `destination`. Overwrites any existing backup.
    /// - Parameter destination: The URL to write the backup file to (e.g. `therecord.duckdb.bak`).
    /// - Throws: `StorageError.writeFailed` if no database path is available or the copy fails.
    public func backupDatabase(to destination: URL) async throws {
        // Prefer explicit databasePath; fall back to global registry; finally query PRAGMA database_list.
        let source = databasePath ?? DatabasePathRegistry.path(for: database) ?? resolvedDatabasePath()
        guard let source else {
            throw StorageError.writeFailed(underlying: nil)
        }
        try await backupDatabase(source: source, to: destination)
    }

    /// Queries `PRAGMA database_list` on the current connection to determine the backing file.
    /// Returns nil for in-memory databases (file column is empty string).
    private func resolvedDatabasePath() -> URL? {
        guard let result = try? connection.query("PRAGMA database_list"),
              result.rowCount > 0 else { return nil }
        // PRAGMA database_list columns: seq (INT32), name (VARCHAR), file (VARCHAR)
        let fileCol = result[2].cast(to: String.self)
        for i in 0 ..< result.rowCount {
            if let path = fileCol[i], !path.isEmpty {
                return URL(fileURLWithPath: path)
            }
        }
        return nil
    }

    /// Copies `source` database file to `destination`. Overwrites any existing backup.
    public func backupDatabase(source: URL, to destination: URL) async throws {
        do {
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try FileManager.default.copyItem(at: source, to: destination)
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

// MARK: - Backup

public extension DuckDBWriterActor {

    /// Backs up the writer's own database file to `destination`.
    ///
    /// Issues CHECKPOINT to flush the WAL before copying so the on-disk file
    /// is consistent. Overwrites any existing file at `destination` (single-generation).
    ///
    /// - Throws: `StorageError.writeFailed` when the database is in-memory (no
    ///   file path) or when the file copy fails. Errors are catchable — callers
    ///   should log and continue rather than crashing (best-effort backup).
    func backupDatabase(to destination: URL) async throws {
        try connection.execute("CHECKPOINT")

        // duckdb_databases() introspection: returns (database_name, path, comment, tags, readonly).
        // Filter out in-memory rows whose path is the empty string.
        let result = try connection.query(
            "SELECT path FROM duckdb_databases() WHERE path != '' LIMIT 1"
        )
        let filePaths = result[0].cast(to: String.self)
        guard let rawPath = filePaths[0], !rawPath.isEmpty else {
            throw StorageError.writeFailed(underlying: nil)
        }
        try Self.copyFile(from: URL(fileURLWithPath: rawPath), to: destination)
    }

    /// Backs up an arbitrary `source` database file to `destination`.
    ///
    /// The writer actor holds the exclusive write lock during the copy.
    /// CHECKPOINT is attempted as a best-effort WAL flush — failure is logged
    /// internally and does not abort the backup (the caller's source file may
    /// belong to a different database instance).
    /// Overwrites any existing file at `destination` (single-generation).
    func backupDatabase(source: URL, to destination: URL) async throws {
        // Best-effort WAL flush; ignore failure — source may not be our database.
        try? connection.execute("CHECKPOINT")
        try Self.copyFile(from: source, to: destination)
    }

    // MARK: - Private helpers

    private static func copyFile(from source: URL, to destination: URL) throws {
        let fm = FileManager.default
        // Remove any existing backup before copying (single-generation — no rotation).
        if fm.fileExists(atPath: destination.path) {
            do {
                try fm.removeItem(at: destination)
            } catch {
                throw StorageError.writeFailed(underlying: error)
            }
        }
        do {
            try fm.copyItem(at: source, to: destination)
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

import Foundation
import Security

/// Reads and writes provider API keys to a secure store.
///
/// The live ``KeychainCredentialStore`` persists keys to the macOS Keychain.
/// Tests inject a mock implementation to avoid Keychain access.
public protocol CredentialStore: Sendable {
    /// Returns the credential for `providerID`, or `nil` if none is stored.
    func credential(for providerID: String) throws -> String?
    /// Writes `credential` for `providerID`, replacing any existing value.
    func store(credential: String, for providerID: String) throws
}

// MARK: - KeychainError

/// Typed error enum for Keychain operations (issue #125).
public enum KeychainError: Error, Sendable, Equatable {
    case itemNotFound
    case accessDenied
    case duplicateItem
    case unexpectedData
    case osStatus(OSStatus)
}

// MARK: - KeychainService

/// Unified Keychain protocol exposing save, load, delete, and deleteAll (issue #125).
public protocol KeychainService: Sendable {
    /// Saves `secret` for the given `account`, replacing any existing value.
    func save(_ secret: String, account: String) throws
    /// Returns the secret for `account`, or `nil` if none is stored.
    func load(account: String) throws -> String?
    /// Returns the secret for `account`, or throws `KeychainError.itemNotFound`.
    func loadOrThrow(account: String) throws -> String
    /// Deletes the secret for `account`.
    func delete(account: String) throws
    /// Deletes all items owned by this service.
    func deleteAll() throws
}

// MARK: - LiveKeychainService

/// Live Keychain implementation (issue #125).
public final class LiveKeychainService: KeychainService {
    /// `kSecAttrSynchronizable` is explicitly `false` so tokens never sync to iCloud Keychain.
    public static let synchronizable: Bool = false

    /// Keychain access group scoped to this app.
    public static let accessGroup: String = "$(AppIdentifierPrefix)com.kasr.therecord"

    private let service: String

    public init(service: String = "app.the-record") {
        self.service = service
    }

    public func save(_ secret: String, account: String) throws {
        guard let data = secret.data(using: .utf8) else {
            throw KeychainError.unexpectedData
        }
        // Delete first to allow update.
        let deleteQuery: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: account,
        ]
        SecItemDelete(deleteQuery as CFDictionary)

        var addQuery: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: account,
            kSecValueData: data,
            kSecAttrAccessible: kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
            kSecAttrSynchronizable: kCFBooleanFalse as Any,
        ]
        if !Self.accessGroup.isEmpty {
            addQuery[kSecAttrAccessGroup] = Self.accessGroup
        }
        let status = SecItemAdd(addQuery as CFDictionary, nil)
        if status == errSecDuplicateItem { throw KeychainError.duplicateItem }
        guard status == errSecSuccess else { throw KeychainError.osStatus(status) }
    }

    public func load(account: String) throws -> String? {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: account,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitOne,
        ]
        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        if status == errSecItemNotFound { return nil }
        guard status == errSecSuccess,
              let data = result as? Data,
              let string = String(data: data, encoding: .utf8)
        else { throw KeychainError.osStatus(status) }
        return string
    }

    public func loadOrThrow(account: String) throws -> String {
        guard let value = try load(account: account) else {
            throw KeychainError.itemNotFound
        }
        return value
    }

    public func delete(account: String) throws {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: account,
        ]
        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw KeychainError.osStatus(status)
        }
    }

    public func deleteAll() throws {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
        ]
        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw KeychainError.osStatus(status)
        }
    }
}

/// Persists provider API keys in the macOS Keychain.
///
/// Keychain parameters: `kSecClassGenericPassword`,
/// service `app.the-record.mcp`, account = `providerID`.
public final class KeychainCredentialStore: CredentialStore {
    /// Accessibility level used for all stored credentials.
    ///
    /// `kSecAttrAccessibleWhenUnlockedThisDeviceOnly` prevents iCloud Keychain sync and
    /// ensures MCP API keys are never migrated to other devices or accessible from
    /// background daemons while the device is locked.
    ///
    /// Stored as `String` (bridged from `CFString`) to satisfy Swift 6 Sendable requirements.
    public static let keychainAccessibility: String =
        kSecAttrAccessibleWhenUnlockedThisDeviceOnly as String

    private let service: String

    public init(service: String = "app.the-record.mcp") {
        self.service = service
    }

    public func credential(for providerID: String) throws -> String? {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: providerID,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitOne,
        ]
        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        if status == errSecItemNotFound { return nil }
        guard status == errSecSuccess,
              let data = result as? Data,
              let string = String(data: data, encoding: .utf8)
        else {
            throw CredentialStoreError.keychainReadFailed(status: status)
        }
        return string
    }

    public func store(credential: String, for providerID: String) throws {
        guard let data = credential.data(using: .utf8) else {
            throw CredentialStoreError.encodingFailed
        }
        // Delete existing entry first to allow update.
        let delete: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: providerID,
        ]
        SecItemDelete(delete as CFDictionary)

        let add: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecAttrAccount: providerID,
            kSecValueData: data,
            kSecAttrAccessible: Self.keychainAccessibility as CFString,
            kSecAttrSynchronizable: kCFBooleanFalse as Any,
        ]
        let status = SecItemAdd(add as CFDictionary, nil)
        guard status == errSecSuccess else {
            throw CredentialStoreError.keychainWriteFailed(status: status)
        }
    }

    /// Deletes every credential stored under this service (used by "Delete All Data" flow).
    public func deleteAll() throws {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
        ]
        let status = SecItemDelete(query as CFDictionary)
        guard status == errSecSuccess || status == errSecItemNotFound else {
            throw CredentialStoreError.keychainWriteFailed(status: status)
        }
    }

    /// Re-stores any items previously saved with `kSecAttrAccessibleAfterFirstUnlock`
    /// under the correct `kSecAttrAccessibleWhenUnlockedThisDeviceOnly` accessibility.
    ///
    /// Call once at app startup (e.g. from the composition root) to migrate credentials
    /// stored before this security fix was applied.
    public func migrateAccessibilityIfNeeded() throws {
        let query: [CFString: Any] = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrService: service,
            kSecReturnAttributes: true,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitAll,
        ]
        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        guard status == errSecSuccess, let items = result as? [[CFString: Any]] else {
            // No items to migrate or none found — not an error.
            return
        }
        let oldAccessibility = kSecAttrAccessibleAfterFirstUnlock as String
        for item in items {
            guard let accessibility = item[kSecAttrAccessible] as? String,
                  accessibility == oldAccessibility,
                  let account = item[kSecAttrAccount] as? String,
                  let data = item[kSecValueData] as? Data,
                  let credential = String(data: data, encoding: .utf8)
            else { continue }
            // store() deletes the old entry first then re-adds with the new accessibility.
            try store(credential: credential, for: account)
        }
    }
}

public enum CredentialStoreError: Error, Sendable {
    case keychainReadFailed(status: OSStatus)
    case keychainWriteFailed(status: OSStatus)
    case encodingFailed
}

