import AppKit
import Domain
import SwiftUI

@MainActor
public struct MenuBarPopover: View {
    @State var viewModel: MenuBarViewModel
    /// Drives the first-launch onboarding sheet. False when `hasCompletedOnboarding` is already set.
    @State private var showOnboarding: Bool

    public init(viewModel: MenuBarViewModel) {
        _viewModel = State(initialValue: viewModel)
        let hasCompletedOnboarding = UserDefaults.standard.bool(forKey: "hasCompletedOnboarding")
        _showOnboarding = State(initialValue: !hasCompletedOnboarding)
    }

    public var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(viewModel.statusMessage).font(.headline)
            recordingButton
            retranscribeButton
            UpcomingMeetingsListView(
                sections: viewModel.upcomingMeetingSectionsCached,
                isLoading: viewModel.isLoadingUpcomingMeetings,
                reload: { Task { await viewModel.loadUpcomingMeetings() } }
            )
            transcriptionSection
            statusSection
            Divider()
            footerBar
        }
        .frame(width: 320)
        .padding()
        .task {
            await viewModel.loadUpcomingMeetings()
            await viewModel.runStartupCleanup()
        }
    }

    @ViewBuilder
    private var recordingButton: some View {
        switch viewModel.recordingState {
        case .idle:
            Button(String(localized: "Record")) { Task { await viewModel.startRecordingTapped() } }
                .accessibilityLabel(String(localized: "Start recording"))
        case .recording:
            Button {
                Task { await viewModel.stopRecordingTapped() }
            } label: {
                HStack(spacing: 6) {
                    RecordingIndicatorView(isRecording: true)
                    Text(String(localized: "Stop"))
                }
            }
            .accessibilityLabel(String(localized: "Stop recording"))
        case .processing:
            Button(String(localized: "Processing…")) {}
                .disabled(true)
        }
    }

    @ViewBuilder
    private var retranscribeButton: some View {
        if let recordingId = viewModel.cleanupRecordingId, !viewModel.isRecording {
            Button(String(localized: "Re-transcribe from Audio")) {
                Task { _ = await viewModel.runCleanupPass(recordingId: recordingId) }
            }
            .buttonStyle(.bordered)
            .frame(maxWidth: .infinity)
        }
    }

    @ViewBuilder
    private var transcriptionSection: some View {
        if let transcription = viewModel.displayedTranscription {
            HStack {
                passBadge(for: transcription.passType)
                if viewModel.cleanupState.isRunning { ProgressView().scaleEffect(0.7).id("cleanupSpinner") }
                Spacer()
            }
            ScrollView { Text(transcription.fullText).frame(maxWidth: .infinity, alignment: .leading) }
                .id("transcriptionText")
                .accessibilityLabel(String(localized: "Transcription preview"))
        }
    }

    @ViewBuilder
    private var statusSection: some View {
        if viewModel.pipelineState.isDiarizing {
            Text(String(localized: "Diarizing...")).font(.caption).foregroundStyle(.secondary).id("diarizingLabel")
        }
        if let diarized = viewModel.pipelineState.diarizedTranscript, !diarized.segments.isEmpty {
            diarizedSegmentsView(diarized)
        }
        if let progress = viewModel.downloadProgress {
            ProgressView(value: progress.fractionCompleted).id("downloadProgressBar")
        }
        if let warning = viewModel.folderWarning {
            let storageLabel = "Storage: \(String(format: "%.1f", warning.currentSizeGB)) GB"
            Text(storageLabel)
                .foregroundStyle(.orange)
        }
        if let message = viewModel.errorMessage {
            VStack(alignment: .leading, spacing: 6) {
                Text(message).foregroundStyle(.red).id("errorBanner")
                if let deepLink = viewModel.settingsDeepLink {
                    Button(String(localized: "Open Settings")) {
                        NSWorkspace.shared.open(deepLink)
                    }
                    .buttonStyle(.link)
                    .font(.caption)
                    .foregroundStyle(.blue)
                }
            }
        }
    }

    private var footerBar: some View {
        HStack {
            Button(String(localized: "Show Window")) {
                NSApp.windows
                    .first {
                        $0.identifier?
                            .rawValue == "main" || ($0.title == "THE RECORD" && !$0.className.contains("Popover"))
                    }?
                    .makeKeyAndOrderFront(nil)
                NSApp.activate()
            }
            .buttonStyle(.borderless)

            Spacer()

            if let build = Bundle.main.infoDictionary?["CFBundleVersion"] as? String, !build.isEmpty {
                Text(build)
                    .font(.system(.caption2, design: .monospaced))
                    .foregroundStyle(.tertiary)
            }

            Button(String(localized: "Quit")) { NSApp.terminate(nil) }
                .buttonStyle(.borderless)
                .foregroundStyle(.red)
        }
        .padding(.top, 2)
    }
}

