import Domain
import DuckDB
import Foundation
import Logging
import Utilities

public actor DuckDBReaderActor: DiarizationReadRepository, NotesReadRepository, RecordingReadRepository, SummaryReadRepository, TranscriptReadRepository {
    private let storageQueue = DispatchSerialQueue(label: "app.the-record.duckdb", qos: .utility)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        storageQueue.asUnownedSerialExecutor()
    }

    public let database: Database
    // internal (not private): DuckDBReaderActorAdmin.swift accesses these via a cross-file
    // extension in the same module. Swift private is file-scoped; actor isolation is the
    // actual safety boundary here.
    let connection: Connection
    let logger = AppLogger.for(category: "DuckDBStorage")

    public init(databasePath: URL?) throws {
        do {
            let store: Database.Store = if let path = databasePath {
                .file(at: path)
            } else {
                .inMemory
            }
            database = try DuckDBInit.openDatabase(store: store)
            connection = try database.connect()
            try Self.setupSchema(connection: connection)
        } catch {
            print("DUCKDB INIT ERROR: \(error)")
            throw StorageError.readFailed(underlying: error)
        }
    }

    private static func setupSchema(connection: Connection) throws {
        // Required DDL statements — any failure is fatal.
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordings, label: "createRecordings")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSegments, label: "createSegments")
        try executeRequired(connection: connection, sql: DuckDBSQL.createCommitmentsTable, label: "createCommitmentsTable")
        try executeRequired(connection: connection, sql: DuckDBSQL.createMeetingNotes, label: "createMeetingNotes")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSummaries, label: "createSummaries")
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordingsIndex, label: "createRecordingsIndex")

        // Additive migrations — tolerate "already exists" / "duplicate" / "reason: nil" errors.
        // Migration for existing databases: add is_pending if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addIsPendingColumn, label: "addIsPendingColumn")
        // Migration for Epic 21: add word_timings VARCHAR column to diarized_segments if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addWordTimingsColumn, label: "addWordTimingsColumn")
        // Migration for epic-28 / task-003: add cleaned_mic_audio_url column if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addCleanedMicAudioUrlColumn, label: "addCleanedMicAudioUrlColumn")
        // Migration for task-013 / #116: add needs_retranscription flag column if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addNeedsRetranscriptionColumn, label: "addNeedsRetranscriptionColumn")

        try executeRequired(connection: connection, sql: DuckDBSQL.createInferenceTelemetry, label: "createInferenceTelemetry")
    }

    /// Executes a DDL statement that must succeed — any error is fatal.
    private static func executeRequired(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            throw error
        }
    }

    /// Executes an additive migration statement. Errors that indicate the column/table already
    /// exists ("exists", "duplicate", "reason: nil") are silently swallowed; others are rethrown.
    private static func executeMigration(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            let desc = String(describing: error).lowercased()
            if !desc.contains("exists"), !desc.contains("duplicate"), !desc.contains("reason: nil") {
                throw error
            }
        }
    }

    public init() throws {
        let dbDir = Directories.appSupport
        try Directories.ensureDirectory(at: dbDir)
        let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.databaseFileName)
        try self.init(databasePath: dbURL)
    }

    // MARK: - Prepared Statement Helper

    func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)
    }
}

import Domain
import DuckDB
import Foundation

// MARK: - MigrationStep

/// A single versioned, named schema migration step.
public struct MigrationStep: Sendable {
    /// Human-readable name for logging and diagnostics.
    public let name: String

    /// The schema version the database must be at before this step can run.
    public let fromVersion: Int32

    /// The schema version the database will be at after this step runs successfully.
    public let toVersion: Int32

    /// The migration closure. Receives an open `Connection` and must apply schema changes.
    /// Throwing here will cause the runner to roll back and rethrow as `StorageError.migrationFailed`.
    public let migrate: @Sendable (Connection) throws -> Void

    public init(
        name: String,
        fromVersion: Int32,
        toVersion: Int32,
        migrate: @escaping @Sendable (Connection) throws -> Void
    ) {
        self.name = name
        self.fromVersion = fromVersion
        self.toVersion = toVersion
        self.migrate = migrate
    }
}

// MARK: - DuckDBMigrationRunner

/// Executes versioned, ordered, idempotent schema migrations against a DuckDB connection.
///
/// Schema version is tracked via `PRAGMA user_version` (an integer stored in the DuckDB file header).
/// On each `migrate(connection:)` call, only steps whose `fromVersion` matches the current version
/// are applied — already-applied steps are skipped.
///
/// Each step is wrapped in a BEGIN/ROLLBACK transaction. If a step throws, the transaction is
/// rolled back and `StorageError.migrationFailed` is thrown — leaving `user_version` unchanged.
public final class DuckDBMigrationRunner: Sendable {

    // MARK: - Public state

    /// Ordered list of migration steps this runner will apply.
    public let steps: [MigrationStep]

    /// The schema version that a fully-migrated database should be at.
    public var currentSchemaVersion: Int32 {
        steps.last?.toVersion ?? 0
    }

    /// Versions applied during the most recent `migrate(connection:)` call (ascending order).
    /// Protected by the serial nature of `migrate` — callers must `await` before reading.
    public nonisolated(unsafe) private(set) var appliedVersions: [Int32] = []

    // MARK: - Init

    /// Creates a runner with an explicit set of steps (primarily for testing).
    public init(steps: [MigrationStep]) {
        self.steps = steps
    }

    /// Creates a runner with the production migration plan.
    public convenience init() {
        self.init(steps: DuckDBMigrationRunner.productionSteps)
    }

    // MARK: - migrate

    /// Applies all pending migrations to `connection` in ascending version order.
    ///
    /// Each step is wrapped in an explicit transaction. On failure the transaction is rolled
    /// back and `StorageError.migrationFailed` is thrown. The `user_version` pragma is updated
    /// inside the same transaction so it stays in sync.
    ///
    /// Calling `migrate` again after a successful run is a no-op.
    public func migrate(connection: Connection) async throws {
        var applied: [Int32] = []

        for step in steps {
            let currentVersion = try readUserVersion(connection: connection)

            // Skip steps that have already been applied.
            guard currentVersion == step.fromVersion else {
                continue
            }

            // Each step runs inside a transaction so partial DDL can be rolled back.
            do {
                try connection.execute("BEGIN TRANSACTION")
                try step.migrate(connection)
                try connection.execute("PRAGMA user_version = \(step.toVersion)")
                try connection.execute("COMMIT")
                applied.append(step.toVersion)
            } catch {
                // Roll back the partial work and re-throw as a StorageError.
                try? connection.execute("ROLLBACK")
                throw StorageError.migrationFailed(underlying: AnyError(error))
            }
        }

        appliedVersions = applied
    }

    // MARK: - Helpers

    private func readUserVersion(connection: Connection) throws -> Int32 {
        let result = try connection.query("PRAGMA user_version")
        let col = result[0].cast(to: Int32.self)
        return col[0] ?? 0
    }
}

// MARK: - AnyError (Sendable wrapper)

/// Wraps any non-Sendable error to satisfy `StorageError.migrationFailed(underlying:)`.
private struct AnyError: Error, Sendable {
    let message: String
    init(_ error: any Error) {
        self.message = error.localizedDescription
    }
}

// MARK: - Production migration plan

extension DuckDBMigrationRunner {
    /// The ordered list of production schema migrations.
    ///
    /// Version history:
    ///   v0 → v1 : Create core tables (recordings, diarized_segments, summaries, meeting_notes,
    ///             commitments, inference_telemetry) + indexes
    ///   v1 → v2 : Add `is_pending` column to recordings
    ///   v2 → v3 : Add `word_timings` column to diarized_segments
    ///   v3 → v4 : Add `cleaned_mic_audio_url` column to recordings (epic-28)
    static let productionSteps: [MigrationStep] = [
        MigrationStep(
            name: "v0→v1: create-core-tables",
            fromVersion: 0,
            toVersion: 1,
            migrate: { conn in
                try conn.execute(DuckDBSQL.createRecordings)
                try conn.execute(DuckDBSQL.createSegments)
                try conn.execute(DuckDBSQL.createSummaries)
                try conn.execute(DuckDBSQL.createMeetingNotes)
                try conn.execute(DuckDBSQL.createCommitmentsTable)
                try conn.execute(DuckDBSQL.createInferenceTelemetry)
                try conn.execute(DuckDBSQL.createRecordingsIndex)
                try conn.execute(DuckDBSQL.createCommitmentsStatusIndex)
                try conn.execute(DuckDBSQL.createCommitmentsMeetingIndex)
            }
        ),
        MigrationStep(
            name: "v1→v2: add-is-pending-column",
            fromVersion: 1,
            toVersion: 2,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addIsPendingColumn)
            }
        ),
        MigrationStep(
            name: "v2→v3: add-word-timings-column",
            fromVersion: 2,
            toVersion: 3,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addWordTimingsColumn)
            }
        ),
        MigrationStep(
            name: "v3→v4: add-cleaned-mic-audio-url-column",
            fromVersion: 3,
            toVersion: 4,
            migrate: { conn in
                try conn.execute(DuckDBSQL.addCleanedMicAudioUrlColumn)
            }
        ),
    ]
}

