extension MenuBarPopover {
    func passBadge(for passType: TranscriptionPassType) -> some View {
        let label = passType == .live ? "Live" : "Final"
        return Text(label)
            .font(.caption2)
            .padding(.horizontal, 6).padding(.vertical, 2)
            .background(passType == .live ? Color.orange : Color.green)
            .foregroundStyle(.white)
            .clipShape(RoundedRectangle(cornerRadius: 4))
    }

    func diarizedSegmentsView(_ diarized: DiarizedTranscript) -> some View {
        let paletteColors: [Color] = [.blue, .green, .orange, .purple]
        let speakerColors: [SpeakerID: Color] = {
            var seen: [SpeakerID] = []
            for seg in diarized.segments where !seen.contains(seg.speakerId) {
                seen.append(seg.speakerId)
            }
            return Dictionary(uniqueKeysWithValues: seen.enumerated().map { idx, id in
                (id, paletteColors[idx % paletteColors.count])
            })
        }()
        return ScrollView {
            LazyVStack(alignment: .leading, spacing: 4) {
                ForEach(diarized.segments, id: \.id) { segment in
                    let color = speakerColors[segment.speakerId] ?? .blue
                    HStack(alignment: .top, spacing: 6) {
                        Text(segment.speakerId.rawValue)
                            .font(.caption2).padding(.horizontal, 4).padding(.vertical, 2)
                            .background(color.opacity(0.2)).foregroundStyle(color)
                            .clipShape(RoundedRectangle(cornerRadius: 3))
                        Text(segment.text).frame(maxWidth: .infinity, alignment: .leading)
                    }
                }
            }
        }
        .id("diarizedTranscriptView")
    }
}

